  q('ex-current-name').textContent=competitor==='manual'?'Your current costs':competitor==='booksy'?'Booksy':competitor==='fresha'?'Fresha':competitor==='treatwell'?'Treatwell Connect':competitor==='acuity'?'Acuity Scheduling':competitor==='squarespace'?'Squarespace':'Solo';
