  q('ex-saving-heading').textContent=r.saving>0?'Estimated annual savings':r.saving<0?'JovaBook would cost':'Your recurring costs match';q('ex-saving').textContent=fmt(r.saving*12);q('ex-saving-unit').textContent=r.saving<0?'more per year':r.saving>0?'saved per year':'per year';q('ex-saving-annual').textContent=fmt(r.saving);q('ex-saving-annual-text').textContent=r.saving<0?'more per month':'saved per month';
