 const summary=document.createElement('summary');summary.textContent='Adjust your figures';settings.append(summary,inputs);grid.append(settings);
 const method=root.querySelector('.ex-comparison details:not(.nr-more-inputs):not(.vp-settings)');if(method)settings.append(method);
 const official={fresha:'https://www.fresha.com/en-GB/pricing',treatwell:'https://www.treatwell.co.uk/partners/pricing/',booksy:'https://biz.booksy.com/en-gb/pricing',acuity:'https://www.acuityscheduling.com/pricing/',squarespace:'https://www.squarespace.com/pricing'};
