  q('vp-example').textContent=key==='squarespace'?'Website costs only: Squarespace Basic vs JovaBook’s included one-page website.':key==='acuity'?'Uses the GBP cost on your bill. Add any separate website cost under the figures.':acquisition?'Example: '+q('ex-new-clients').value+' new marketplace clients a month at £'+Number(q('ex-first-value').value).toLocaleString('en-GB')+'.':'Example: Booksy’s standard subscription, with Boost off.';
